patch:
diff --git a/runtime/nvidia/interp_sm120.cu b/runtime/nvidia/interp_sm120.cu
index 56a0b3af..b7d71c34 100644
--- a/runtime/nvidia/interp_sm120.cu
+++ b/runtime/nvidia/interp_sm120.cu
@@ -731,7 +731,9 @@ __device__ __forceinline__ PlowStreamEnt ld_stream_ent(const PlowStreamEnt* p) {
 #ifndef PLOW_NV_FA128_BKV
 #define PLOW_NV_FA128_BKV 64
 #endif
-#if defined(PLOW_NV_HOPPER) && PLOW_NV_FA512_WG
+#if defined(PLOW_NV_HOPPER) && PLOW_NV_FA_FP8_WGMMA
+#define PLOW_NV_PRE_A512 FA_SM90_PRE_FLOATS(512, 64, 32)
+#elif defined(PLOW_NV_HOPPER) && PLOW_NV_FA512_WG
 #define PLOW_NV_PRE_A512 FA_PRE_SMEM_FLOATS(512, 64, PLOW_NV_FA512_BKV)
 #else
 #define PLOW_NV_PRE_A512 FA_PRE_SMEM_FLOATS(512, 32, 16)
diff --git a/runtime/nvidia/op_attention.cuh b/runtime/nvidia/op_attention.cuh
index bad3a5d4..b510f625 100644
--- a/runtime/nvidia/op_attention.cuh
+++ b/runtime/nvidia/op_attention.cuh
@@ -3739,6 +3739,10 @@ __device__ void d_flash_prefill_mux(const int* __restrict__ req, float* __restri
     }
 }

+#ifndef PLOW_NV_FA_FP8_WGMMA
+#define PLOW_NV_FA_FP8_WGMMA 0
+#endif
+
 #if PLOW_FP8_KV && PLOW_NV_PACKED_REQUEST
 template <int HD>
 __device__ void d_flash_prefill_fp8_mux(
@@ -3764,6 +3768,18 @@ __device__ void d_flash_prefill_fp8_mux(
         (const __nv_bfloat16*)(K + soff * HD), (const __nv_bfloat16*)(V + soff * HD), \
         O ? O + qoff : nullptr, qlen, kvlen, n_head, n_kv_head, pos0, window, nsplit, \
         kv_stride, kv_mask, scale, slice, nblk, lds, k_scale + soff, v_scale + soff
+#if defined(PLOW_NV_HOPPER) && PLOW_NV_FA_FP8_WGMMA
+        if constexpr (HD == 512) {
+            d_flash_prefill_sm90<512, 64, 32, true>(
+                Opart + qoff * nsplit, mlpart + (size_t)q0 * n_head * nsplit * 2,
+                Q + qoff, (const __nv_bfloat16*)(K + soff * HD),
+                (const __nv_bfloat16*)(V + soff * HD), O ? O + qoff : nullptr,
+                qlen, kvlen, n_head, n_kv_head, pos0, window, nsplit, kv_stride,
+                kv_mask, scale, slice, nblk, lds, nullptr, nullptr,
+                k_scale + soff, v_scale + soff);
+        } else
+#endif
+        {
 #if PLOW_NV_FA_PIPE
 #if PLOW_NV_FA_FP8MMA
         if constexpr (HD == 256) {
@@ -3781,6 +3797,7 @@ __device__ void d_flash_prefill_fp8_mux(
 #else
         d_flash_prefill<HD, HD == 256 ? 64 : 32, HD == 256 ? 32 : 16, true>(PLOW_FP8_REQUEST_ARGS);
 #endif
+        }
 #undef PLOW_FP8_REQUEST_ARGS
         __syncthreads();
     }
diff --git a/runtime/nvidia/op_attention_sm90.cuh b/runtime/nvidia/op_attention_sm90.cuh
index ba268a69..10b149af 100644
--- a/runtime/nvidia/op_attention_sm90.cuh
+++ b/runtime/nvidia/op_attention_sm90.cuh
@@ -548,7 +548,7 @@ __device__ void d_flash_prefill_sm90_wgitem(
 }

 /* ============================ the kernel body ============================================== */
-template <int HD, int BQ, int BKV>
+template <int HD, int BQ, int BKV, bool FP8KV = false>
 __device__ void d_flash_prefill_sm90(float* __restrict__ Opart, float* __restrict__ mlpart,
                                      const __nv_bfloat16* __restrict__ Q,
                                      const __nv_bfloat16* __restrict__ K,
@@ -559,9 +559,11 @@ __device__ void d_flash_prefill_sm90(float* __restrict__ Opart, float* __restric
                                      unsigned kv_stride, unsigned kv_mask, float scale,
                                      unsigned slice, unsigned nblk, float* lds,
                                      const int* __restrict__ req,
-                                     const void* __restrict__ mapkv = nullptr) {
+                                     const void* __restrict__ mapkv = nullptr,
+                                     const float* __restrict__ k_scale = nullptr,
+                                     const float* __restrict__ v_scale = nullptr) {
 #if PLOW_NV_FA_WGITEM
-    if constexpr (HD == 256 && BKV == 32) {
+    if constexpr (!FP8KV && HD == 256 && BKV == 32) {
         d_flash_prefill_sm90_wgitem<HD, BQ, BKV>(Opart, mlpart, Q, K, V, O, seq_q, seq_kv,
                                                  n_head, n_kv_head, q_pos0, window, nsplit,
                                                  kv_stride, kv_mask, scale, slice, nblk, lds,
@@ -708,7 +710,7 @@ __device__ void d_flash_prefill_sm90(float* __restrict__ Opart, float* __restric
          * count, and waitKV() then spins forever (reachable via the documented
          * -DPLOW_NV_FA512_WG=1 -DPLOW_NV_FA_PX4=0 build). BKV is a template constant, so this
          * term folds away; a sub-32 BKV simply keeps the cp.async path below. */
-        const bool use_tma = item_mapkv != nullptr && (BKV % 32 == 0);
+        const bool use_tma = !FP8KV && item_mapkv != nullptr && (BKV % 32 == 0);
         auto stageKV = [&](unsigned kv0, int buf) {
             __nv_bfloat16* kd = Ks + (size_t)buf * NSUB * KT;
             __nv_bfloat16* vd = Vs + (size_t)buf * NSUB * KT;
@@ -740,8 +742,29 @@ __device__ void d_flash_prefill_sm90(float* __restrict__ Opart, float* __restric
                 const size_t row = (size_t)(kv & kv_mask);
                 const int soff = sub * KT + sm90_swz_off<64, 8>(r, c);
                 const size_t goff = in ? row * HD + (size_t)sub * 64 + (size_t)c * 8 : 0;
-                sm90_cp16(kd + soff, Kb + goff, in ? 16 : 0);
-                sm90_cp16(vd + soff, Vb + goff, in ? 16 : 0);
+                if constexpr (FP8KV) {
+                    // FP8 addresses count bytes; scales count rows, including the packed slot.
+                    const size_t base = kvoff + (size_t)hkv * kv_stride * HD;
+                    const size_t sr = base / HD + row;
+                    bf16v8 kk, vv;
+#pragma unroll
+                    for (int j = 0; j < 8; ++j) kk.x[j] = vv.x[j] = __float2bfloat16(0.0f);
+                    if (in) {
+                        const uint2 kb = *(const uint2*)((const uint8_t*)K + base + goff);
+                        const uint2 vb = *(const uint2*)((const uint8_t*)V + base + goff);
+                        const float ks = k_scale[sr], vs = v_scale[sr];
+#pragma unroll
+                        for (int j = 0; j < 8; ++j) {
+                            kk.x[j] = __float2bfloat16(fp8_to_f32(((const uint8_t*)&kb)[j]) * ks);
+                            vv.x[j] = __float2bfloat16(fp8_to_f32(((const uint8_t*)&vb)[j]) * vs);
+                        }
+                    }
+                    *(bf16v8*)(kd + soff) = kk;
+                    *(bf16v8*)(vd + soff) = vv;
+                } else {
+                    sm90_cp16(kd + soff, Kb + goff, in ? 16 : 0);
+                    sm90_cp16(vd + soff, Vb + goff, in ? 16 : 0);
+                }
             }
             sm90_cp_commit();
         };
